import * as React from "react"

function BuyMeACoffeeFloatingButton({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="buy-me-a-coffee-floating-button"
      className={className}
      {...props}
    >
      <div className="fixed bottom-6 right-6">
          <a href="https://www.buymeacoffee.com/yourusername" target="_blank" rel="noopener noreferrer"
              className="bg-yellow-500 text-white font-medium rounded-md px-4 py-2 flex items-center justify-center hover:bg-yellow-600 transition duration-300 ease-in-out shadow-lg">
              <span className="text-lg mr-2">☕</span>
              Buy me a coffee
          </a>
      </div>
    </div>
  )
}

export { BuyMeACoffeeFloatingButton }
